data.query:
query(
  $wherePO: PurchaseOrderWhereInput,
  $whereR: ReceiptWhereInput,
  $whereL: PurchaseOrderLineWhereInput,
  $whereRL: ReceiptLineWhereInput
) {
  po:purchaseOrder(where: $wherePO) {edges {node {
    number
    facilityId
    purchaseOrderStatusId
    supplierId
    receipts(where:$whereR){edges{node{
      id
    }}}
    outsourceWorkOrderProcesses{edges{node{
      workOrderId
      id
    }}}

    lines(where: $whereL){edges{node{
      id
      code
      balanceQuantity  {value unitId}
      pendingQuantity  {value unitId}
      quantity         {value unitId}
      receivedQuantity {value unitId}
      product{id productTypeId}
      purchaseOrderLineStatusId
      productStrategyProcess {
        id
        productStrategy {
          inventoryUnitId
        }
        lotControl {
          id
          maturityDays
          shelfLifeDays
          holdDays
          defaultExpirationActionId
        }
      }

      receiptLines(where: $whereRL){edges{node {
        id quantity{value unitId} 
      }}}
    }}}
  }}}
}

data.transform:
po.edges.node.lines.edges.node.(
  $id := id;
  $unitId := pendingQuantity.unitId;
  $line := $lookup($state.context.REQUEST.DATA.lines,$id);
  $pending := pendingQuantity.value + $line.(qtyPer * containers);
  $balance := balanceQuantity.value - $line.(qtyPer * containers);
  {
    "id": $id,
    "code":code,
    "success": $balance >= 0,
    "pending": $pending,
    "balance": $balance,
    "exceeded": $balance < 0 
      ? 0-$balance 
      : 0,
    "unitId": $unitId
  }
)

